	ctx := mock.Anything
	drvr := &mockdriver.Readdirer{}
	drvr.On("Readdir", ctx, "").Return([]os.FileInfo{
		mockFile("A", true),
		mockFile("B", false),
	}, nil).Once()
	drvr.On("Readdir", ctx, "A").Return([]os.FileInfo{
		mockFile("AA", true),
		mockFile("AB", true),
		mockFile("AC", false),
	}, nil).Once()
	drvr.On("Readdir", ctx, "A/AA").Return([]os.FileInfo{
		mockFile("1", false),
		mockFile("2", false),
	}, nil).Once()
	drvr.On("Readdir", ctx, "A/AB").Return([]os.FileInfo{
		mockFile("3", false),
